import 'dart:async';

import 'package:flutter/foundation.dart';

import '../entities/app_user.dart';
import '../services/auth/firebase_auth_service.dart';

class AuthSessionProvider extends ChangeNotifier {
  AuthSessionProvider({required FirebaseAuthService authService})
      : _authService = authService {
    _user = _authService.currentUser;
    _isReady = _user != null;
    _subscription = _authService.authStateChanges().listen(_handleAuthChange);
  }

  final FirebaseAuthService _authService;
  late final StreamSubscription<AppUser?> _subscription;

  AppUser? _user;
  bool _isReady = false;

  AppUser? get user => _user;
  bool get isAuthenticated => _user != null;
  bool get isReady => _isReady;

  void _handleAuthChange(AppUser? user) {
    _user = user;
    if (!_isReady) {
      _isReady = true;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _subscription.cancel();
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:provider/provider.dart';

import '../../../../core/constants/app_assets.dart';
import '../../../../core/extensions/responsive_extension.dart';
import '../../../../core/providers/auth_session_provider.dart';
import '../../../../core/router/route_names.dart';
import '../../../../core/theme/app_colors.dart';
import '../../../../core/theme/app_spacing.dart';
import '../../../../core/utils/system_utils.dart';
import '../widgets/splash_text_widgets.dart';
import '../widgets/splash_visual_widgets.dart';

class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});

  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _pulseController;
  late final AuthSessionProvider _authSessionProvider;
  Timer? _navigationTimer;
  VoidCallback? _authListener;

  @override
  void initState() {
    super.initState();
    _authSessionProvider = context.read<AuthSessionProvider>();
    SystemUtils.enableFullScreen();
    SystemUtils.setCustomSystemUI(
      statusBarIconBrightness: Brightness.light,
      statusBarBrightness: Brightness.dark,
      navigationBarColor: Colors.transparent,
      navigationBarIconBrightness: Brightness.light,
    );
    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    )..repeat(reverse: true);

    _navigationTimer = Timer(
      const Duration(seconds: 3),
      _handleSplashComplete,
    );
  }

  @override
  void dispose() {
    _navigationTimer?.cancel();
    if (_authListener != null) {
      _authSessionProvider.removeListener(_authListener!);
    }
    _pulseController.dispose();
    SystemUtils.disableFullScreen();
    SystemUtils.setDefaultSystemUI();
    super.dispose();
  }

  void _handleSplashComplete() {
    if (!mounted) return;

    if (!_authSessionProvider.isReady) {
      _authListener = () {
        if (!_authSessionProvider.isReady || !mounted) return;
        _authSessionProvider.removeListener(_authListener!);
        _authListener = null;
        _navigateFromSplash();
      };
      _authSessionProvider.addListener(_authListener!);
      return;
    }

    _navigateFromSplash();
  }

  void _navigateFromSplash() {
    final String targetRoute = _authSessionProvider.isAuthenticated
        ? RouteNames.navbar
        : RouteNames.onboarding;
    context.go(targetRoute);
  }

  Animation<double> _dotAnimation(double start) {
    return CurvedAnimation(
      parent: _pulseController,
      curve: Interval(start, start + 0.6, curve: Curves.easeInOut),
    );
  }

  @override
  Widget build(BuildContext context) {
    final double contentPadding = AppSpacing.x2l + AppSpacing.sm;
    final double topOffset = (AppSpacing.x2l * 3) + AppSpacing.sm;
    final double leftOffset = AppSpacing.x2l + AppSpacing.lg;
    final double bottomOffset = (AppSpacing.x2l * 2) + AppSpacing.lg;

    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [AppColors.lightGreen, AppColors.primary],
          ),
        ),
        child: Stack(
          children: [
            SplashBackgroundIcon(
              asset: AppAssets.leaf,
              top: topOffset,
              left: leftOffset,
              size: (AppSpacing.x2l * 5) + AppSpacing.sm,
            ),
            SplashBackgroundIcon(
              asset: AppAssets.router,
              bottom: AppSpacing.x2l * 5 + AppSpacing.sm,
              right: leftOffset,
              size: AppSpacing.x2l * 4,
            ),
            Positioned.fill(
              child: Padding(
                padding: EdgeInsets.symmetric(
                  horizontal: contentPadding.w,
                ),
                child: Column(
                  children: [
                    const Spacer(),
                    const SplashLogoTile(),
                    AppSpacing.x2l.ht,
                    const SplashTitle(),
                    AppSpacing.sm.ht,
                    const SplashTagline(),
                    const Spacer(),
                  ],
                ),
              ),
            ),
            Positioned(
              left: 0,
              right: 0,
              bottom: bottomOffset.h,
              child: SplashPagerDots(
                animations: [
                  _dotAnimation(0.0),
                  _dotAnimation(0.2),
                  _dotAnimation(0.4),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:agrisenseaiapp/core/extensions/context_extensions.dart';
import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:provider/provider.dart';

import '../../../../app/injection_container.dart';
import '../../../../core/extensions/responsive_extension.dart';
import '../../../../core/providers/auth_session_provider.dart';
import '../../../../core/router/route_names.dart';
import '../../../../core/theme/app_colors.dart';
import '../../../../core/theme/app_spacing.dart';
import '../../../../core/utils/system_utils.dart';
import '../providers/onboarding_provider.dart';
import '../widgets/onboarding_control_widgets.dart';
import '../widgets/onboarding_visual_widgets.dart';

class OnboardingScreen extends StatelessWidget {
  const OnboardingScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return ChangeNotifierProvider<OnboardingProvider>(
      create: (_) => di<OnboardingProvider>(),
      child: const _OnboardingScreenContent(),
    );
  }
}

class _OnboardingScreenContent extends StatefulWidget {
  const _OnboardingScreenContent();

  @override
  State<_OnboardingScreenContent> createState() =>
      _OnboardingScreenContentState();
}

class _OnboardingScreenContentState extends State<_OnboardingScreenContent> {
  late PageController _pageController;

  @override
  void initState() {
    super.initState();
    SystemUtils.enableFullScreen();
    SystemUtils.setCustomSystemUI(
      statusBarIconBrightness: Brightness.dark,
      statusBarBrightness: Brightness.light,
      navigationBarColor: Colors.white,
      navigationBarIconBrightness: Brightness.dark,
    );
    _pageController = PageController();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        _initializeOnboarding();
      }
    });
  }

  Future<void> _initializeOnboarding() async {
    final provider =
        Provider.of<OnboardingProvider>(context, listen: false);
    await provider.initialize();
  }

  @override
  void dispose() {
    _pageController.dispose();
    SystemUtils.disableFullScreen();
    SystemUtils.setDefaultSystemUI();
    super.dispose();
  }

  void _handlePageChanged(int index) {
    final provider =
        Provider.of<OnboardingProvider>(context, listen: false);
    provider.goToPage(index);
  }

  void _handleSkip() {
    final authSession = context.read<AuthSessionProvider>();
    final targetRoute = authSession.isAuthenticated
        ? RouteNames.navbar
        : RouteNames.auth;
    context.go(targetRoute);
  }

  void _handleCta() {
    final provider =
        Provider.of<OnboardingProvider>(context, listen: false);
    if (provider.hasNextPage) {
      _pageController.nextPage(
        duration: const Duration(milliseconds: 300),
        curve: Curves.easeOut,
      );
    } else {
      final authSession = context.read<AuthSessionProvider>();
      final targetRoute = authSession.isAuthenticated
          ? RouteNames.navbar
          : RouteNames.auth;
      context.go(targetRoute);
    }
  }

  @override
  Widget build(BuildContext context) {
    final double skipPadding = AppSpacing.x2l;
    final double contentHorizontalPadding = AppSpacing.x2l + AppSpacing.sm;
    final double contentTopPadding = AppSpacing.lg;
    final double footerHorizontalPadding = contentHorizontalPadding;
    final double footerTopPadding = AppSpacing.x2l + AppSpacing.sm;
    final double footerBottomPadding = AppSpacing.x2l + AppSpacing.lg;
    final double footerGap = AppSpacing.x2l + AppSpacing.sm;

    return Scaffold(
      backgroundColor: AppColors.surface,
      body: Consumer<OnboardingProvider>(
        builder: (context, provider, _) {
          if (provider.isLoading) {
            return const Center(child: CircularProgressIndicator());
          }

          if (provider.pages.isEmpty) {
            return Center(
              child: Text('No onboarding pages available', style: context.textTheme.bodyMedium),
            );
          }

          final currentPage = provider.currentPage;

          return Column(
            children: [
              Padding(
                padding: EdgeInsets.symmetric(
                  horizontal: skipPadding.w,
                  vertical: skipPadding.h,
                ),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: OnboardingSkipButton(
                    isVisible: currentPage?.showSkip ?? false,
                    onPressed: _handleSkip,
                  ),
                ),
              ),
              Expanded(
                child: Padding(
                  padding: EdgeInsets.fromLTRB(
                    contentHorizontalPadding.w,
                    contentTopPadding.h,
                    contentHorizontalPadding.w,
                    0,
                  ),
                  child: PageView.builder(
                    controller: _pageController,
                    itemCount: provider.pages.length,
                    onPageChanged: _handlePageChanged,
                    itemBuilder: (context, index) {
                      final page = provider.pages[index];
                      return OnboardingPageContent(
                        title: page.title,
                        description: page.description,
                        illustration: _getIllustrationVariant(
                          page.illustrationType,
                        ),
                      );
                    },
                  ),
                ),
              ),
              Padding(
                padding: EdgeInsets.fromLTRB(
                  footerHorizontalPadding.w,
                  footerTopPadding.h,
                  footerHorizontalPadding.w,
                  footerBottomPadding.h,
                ),
                child: Column(
                  children: [
                    OnboardingPagerIndicator(
                      currentIndex: provider.currentPageIndex,
                      total: provider.totalPages,
                    ),
                    SizedBox(height: footerGap.h),
                    OnboardingPrimaryButton(
                      label: currentPage?.ctaLabel ?? 'Next',
                      iconAsset: currentPage?.ctaIcon ?? '',
                      onPressed: _handleCta,
                    ),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  OnboardingIllustrationVariant _getIllustrationVariant(
    String illustrationType,
  ) {
    return switch (illustrationType) {
      'monitor' => OnboardingIllustrationVariant.monitor,
      'automate' => OnboardingIllustrationVariant.automate,
      'insights' => OnboardingIllustrationVariant.insights,
      _ => OnboardingIllustrationVariant.monitor,
    };
  }
}

